// Gemini Live — web dashboard tab (`hermes dashboard` → Gemini Live).
//
// GENERATED by scripts/build.py from src/dashboard.js + src/engine.js — edit those.
// A plain IIFE on window.__HERMES_PLUGIN_SDK__ (no bundler, React comes from the SDK).
;(function () {
  'use strict'

  const SDK = window.__HERMES_PLUGIN_SDK__
  if (!SDK || !window.__HERMES_PLUGINS__) {
    return
  }

  const React = SDK.React
  const { useEffect, useRef, useState } = SDK.hooks
  const h = React.createElement
  const Button = (SDK.components && SDK.components.Button) || 'button'

  /*@ENGINE@*/

  const PLUGIN_API = '/api/plugins/gemini-live'

  // ── doors ──────────────────────────────────────────────────────────────────────────────────

  async function rest(path, opts) {
    const init = opts && opts.method ? { method: opts.method } : {}

    if (opts && opts.body !== undefined) {
      init.body = JSON.stringify(opts.body)
      init.headers = { 'Content-Type': 'application/json' }
    }

    return SDK.fetchJSON(`${PLUGIN_API}${path}`, init)
  }

  // Minimal JSON-RPC client for the dashboard's own gateway socket (/api/ws). Server→client
  // requests are not advertised, so a turn that needs an approval fails fast instead of
  // waiting on a prompt this tab cannot show.
  function createRpc() {
    let socket = null
    let opening = null
    let nextId = 0
    const pending = new Map()
    const listeners = new Set()

    function open() {
      if (socket && socket.readyState === 1) {
        return Promise.resolve(socket)
      }

      if (opening) {
        return opening
      }

      // SDK.buildWsUrl is the dashboard's own auth path: a single-use ticket in gated mode,
      // the page session otherwise. The plugin never reads a credential itself.
      opening = SDK.buildWsUrl('/api/ws').then(
        url =>
          new Promise((resolve, reject) => {
            const ws = new WebSocket(url)
            ws.onopen = () => {
              socket = ws
              opening = null
              resolve(ws)
            }
            ws.onerror = () => {
              opening = null
              reject(new Error('Could not connect to the Hermes gateway.'))
            }
            ws.onclose = () => {
              if (socket === ws) {
                socket = null
              }
              pending.forEach(p => p.reject(new Error('Gateway connection closed.')))
              pending.clear()
            }
            ws.onmessage = event => {
              let frame
              try {
                frame = JSON.parse(event.data)
              } catch {
                return
              }

              if (frame.method === 'event' && frame.params) {
                listeners.forEach(fn => {
                  try {
                    fn(frame.params)
                  } catch {
                    // a broken listener must not drop the stream
                  }
                })

                return
              }

              if (frame.id !== undefined && pending.has(frame.id)) {
                const p = pending.get(frame.id)
                pending.delete(frame.id)
                window.clearTimeout(p.timer)
                if (frame.error) {
                  p.reject(new Error(frame.error.message || 'Gateway error'))
                } else {
                  p.resolve(frame.result)
                }
              }
            }
          })
      )

      return opening
    }

    async function request(method, params, timeoutMs) {
      const ws = await open()
      const id = `gl${(nextId += 1)}`

      return new Promise((resolve, reject) => {
        const timer = window.setTimeout(() => {
          pending.delete(id)
          reject(new Error(`${method} timed out`))
        }, timeoutMs || 30000)
        pending.set(id, { resolve, reject, timer })
        ws.send(JSON.stringify({ jsonrpc: '2.0', id, method, params: params || {} }))
      })
    }

    return {
      request,
      onEvent(fn) {
        listeners.add(fn)

        return () => listeners.delete(fn)
      },
      close() {
        if (socket) {
          socket.close()
        }
      }
    }
  }

  const rpc = createRpc()
  let voiceSessionId = ''

  const engine = createGeminiLiveEngine({
    rest,
    rpc: (method, params, timeoutMs) => rpc.request(method, params, timeoutMs),
    onEvent: fn => rpc.onEvent(fn),
    focus: () => ({ sessionId: voiceSessionId, storedId: '' }),
    ensureSession: async () => {
      if (!voiceSessionId) {
        const created = await rpc.request('session.create', {}, 30000)
        voiceSessionId = (created && created.session_id) || ''
      }

      return voiceSessionId
    },
    chatContext: async () => ({}),
    log: (level, message) => {
      if (level !== 'debug') {
        console.info(`[gemini-live] ${message}`)
      }
    }
  })

  // ── tiny store hook ────────────────────────────────────────────────────────────────────────

  function useCall() {
    const [call, setCall] = useState(engine.snapshot())

    useEffect(() => engine.subscribe(setCall), [])

    return call
  }

  function phaseLabel(call) {
    if (call.phase === 'connecting') return 'Connecting…'
    if (call.phase === 'reconnecting') return 'Reconnecting…'
    if (call.phase === 'error') return 'Call failed'
    if (call.phase !== 'live') return 'Ready'
    if (call.muted) return call.pausedUntil ? 'Paused' : 'Muted'
    if (call.modelSpeaking) return 'Speaking'
    if (call.delegation && call.delegation.approval) return `${call.agentName} needs you`
    if (call.delegation && call.delegation.status === 'working') return `${call.agentName} is working`
    return call.userSpeaking ? 'Hearing you' : 'Listening'
  }

  function isActive(call) {
    return call.phase === 'connecting' || call.phase === 'live' || call.phase === 'reconnecting'
  }

  function Orb(props) {
    const ref = useRef(null)
    const phaseRef = useRef('idle')
    phaseRef.current = props.phase

    useEffect(() => {
      const canvas = ref.current
      if (!canvas) return undefined
      const size = props.size
      const dpr = window.devicePixelRatio || 1
      canvas.width = size * dpr
      canvas.height = size * dpr
      const g = canvas.getContext('2d')
      const style = getComputedStyle(canvas)
      const accent = style.getPropertyValue('--gl-accent').trim() || style.color
      const reduced = Boolean(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches)
      const orb = glCreateOrb()
      let raf = 0

      const frame = now => {
        orb.draw(g, canvas.width, { ...engine.levels(), ...engine.visual(), phase: phaseRef.current, color: accent, reduced, now })
        raf = window.requestAnimationFrame(frame)
      }

      raf = window.requestAnimationFrame(frame)

      return () => window.cancelAnimationFrame(raf)
    }, [props.size])

    return h('canvas', { className: 'glive-orb', ref, style: { height: `${props.size}px`, width: `${props.size}px` } })
  }

  function Elapsed(props) {
    const [, force] = useState(0)
    useEffect(() => {
      const id = window.setInterval(() => force(n => n + 1), 1000)
      return () => window.clearInterval(id)
    }, [])
    const s = Math.max(0, Math.floor((Date.now() - props.since) / 1000))
    return h('span', { className: 'glive-mono' }, `${Math.floor(s / 60)}:${String(s % 60).padStart(2, '0')}`)
  }

  function Field(props) {
    return h(
      'label',
      { className: 'glive-field' },
      h('span', { className: 'glive-field__label' }, props.label),
      h(
        'select',
        { className: 'glive-native-select', disabled: props.disabled, onChange: e => props.onChange(e.target.value), value: props.value },
        props.options.map(o => h('option', { key: o.id, value: o.id }, o.label))
      )
    )
  }

  function TranscriptView(props) {
    const ref = useRef(null)
    const rows = props.call.transcript
    useEffect(() => {
      if (ref.current) ref.current.scrollTop = ref.current.scrollHeight
    })
    if (!rows.length) return h('div', { className: 'glive-empty' }, 'The conversation appears here as you talk.')
    return h(
      'div',
      { className: 'glive-scroll', ref },
      rows.map(t =>
        h(
          'div',
          { className: `glive-line glive-line--${t.role}`, key: t.id },
          h('span', { className: 'glive-line__who' }, t.role === 'user' ? 'You' : t.role === 'assistant' ? call.agentName : 'Update'),
          h('span', { className: 'glive-line__text' }, t.text)
        )
      )
    )
  }

  function ActivityView(props) {
    const d = props.call.delegation
    const items = props.call.activity.slice().reverse()
    return h(
      'div',
      { className: 'glive-scroll' },
      d
        ? h(
            'div',
            { className: `glive-card glive-card--${d.status}` },
            h(
              'div',
              { className: 'glive-card__head' },
              h('span', { className: 'glive-strong' }, `${call.agentName} ${d.status === 'working' ? 'is working' : d.status === 'done' ? 'finished' : 'stopped'}`),
              d.status === 'working' ? h(Button, { onClick: () => void engine.cancelHermes(), size: 'sm', variant: 'secondary' }, 'Stop') : null
            ),
            h('div', { className: 'glive-card__req' }, d.request),
            d.approval
              ? h(
                  'div',
                  { className: 'glive-card__approval' },
                  h('div', { className: 'glive-strong' }, 'Needs your approval'),
                  h('div', { className: 'glive-mono' }, d.approval.action),
                  h(
                    'div',
                    { className: 'glive-card__actions' },
                    h(Button, { onClick: () => void engine.answerApproval('once'), size: 'sm' }, 'Approve'),
                    h(Button, { onClick: () => void engine.answerApproval('deny'), size: 'sm', variant: 'secondary' }, 'Deny')
                  )
                )
              : null,
            d.status === 'working' && d.lastTool ? h('div', { className: 'glive-dim' }, `Using ${d.lastTool} · ${d.toolCount || 0} tool calls`) : null,
            d.result ? h('div', { className: 'glive-card__result' }, d.result) : null
          )
        : null,
      items.length
        ? items.map(a =>
            h(
              'div',
              { className: `glive-act glive-act--${a.status}`, key: a.id },
              h('span', null, a.status === 'running' ? '…' : a.status === 'done' ? '✓' : '!'),
              h('span', { className: 'glive-strong' }, a.label),
              a.detail ? h('span', { className: 'glive-dim glive-ellipsis' }, a.detail) : null
            )
          )
        : d
          ? null
          : h('div', { className: 'glive-empty' }, 'Tool calls and Hermes work show up here.')
    )
  }

  function ThreadsView(props) {
    const [rows, setRows] = useState(null)
    const [error, setError] = useState('')

    useEffect(() => {
      if (!props.visible) return undefined
      let stop = false
      const load = async () => {
        try {
          const [live, stored] = await Promise.all([
            rpc.request('session.active_list', {}, 10000),
            rpc.request('session.list', { limit: 12 }, 10000)
          ])
          const liveRows = ((live && live.sessions) || []).map(s => ({ id: s.id, title: s.title || 'Untitled', status: s.status, preview: s.preview }))
          const keys = new Set(((live && live.sessions) || []).map(s => s.session_key))
          const storedRows = ((stored && stored.sessions) || [])
            .filter(s => !keys.has(s.id))
            .map(s => ({ id: s.id, title: s.title || 'Untitled', status: 'saved', preview: s.preview }))
          if (!stop) {
            setRows(liveRows.concat(storedRows))
            setError('')
          }
        } catch (err) {
          if (!stop) setError((err && err.message) || String(err))
        }
      }
      void load()
      const id = window.setInterval(load, 5000)
      return () => {
        stop = true
        window.clearInterval(id)
      }
    }, [props.visible])

    if (error) return h('div', { className: 'glive-empty' }, error)
    if (!rows) return h('div', { className: 'glive-empty' }, 'Loading threads…')
    if (!rows.length) return h('div', { className: 'glive-empty' }, 'No threads yet.')
    return h(
      'div',
      { className: 'glive-scroll' },
      rows.map(r =>
        h(
          'div',
          { className: 'glive-thread', key: r.id },
          h('span', { className: `glive-dot glive-dot--${GL_BUSY_STATUSES[r.status] ? 'busy' : 'idle'}` }),
          h(
            'div',
            { className: 'glive-thread__body' },
            h('div', { className: 'glive-thread__title' }, h('span', { className: 'glive-strong glive-ellipsis' }, r.title), h('span', { className: 'glive-dim' }, r.status)),
            r.preview ? h('div', { className: 'glive-dim glive-ellipsis' }, r.preview) : null
          )
        )
      )
    )
  }

  function GeminiLivePage() {
    const call = useCall()
    const [status, setStatus] = useState(null)
    const [models, setModels] = useState([])
    const [tab, setTab] = useState('transcript')
    const [text, setText] = useState('')
    const [choice, setChoice] = useState({ model: '', voice: '', persona: '' })

    useEffect(() => {
      rest('/status')
        .then(s => {
          setStatus(s)
          if (s && s.configured) {
            rest('/models')
              .then(m => setModels((m && m.models) || []))
              .catch(() => undefined)
          }
        })
        .catch(err => setStatus({ ok: false, error: (err && err.message) || String(err) }))
    }, [])

    const live = isActive(call)
    const settings = (status && status.settings) || {}
    const model = choice.model || call.model || settings.model || 'gemini-3.8-live'
    const voice = choice.voice || call.voice || settings.voice || 'Laomedeia'
    const persona = choice.persona || call.persona || settings.persona || 'hermes'
    const modelOptions = models.length ? models.map(m => ({ id: m.id, label: m.label })) : [{ id: model, label: model }]
    if (!modelOptions.some(o => o.id === model)) modelOptions.unshift({ id: model, label: model })
    const voiceOptions = ((status && status.voices) || [voice]).map(v => ({ id: v, label: v }))
    const personaOptions = ((status && status.personas) || [{ id: persona, label: persona }]).map(p => ({ id: p.id, label: p.label }))
    const notConfigured = status && status.ok && !status.configured

    return h(
      'div',
      { className: 'glive-page' },
      h(
        'section',
        { className: 'glive-stage' },
        h(Orb, { phase: call.phase, size: 208 }),
        h('div', { className: 'glive-stage__phase' }, phaseLabel(call)),
        h('div', { className: 'glive-dim' }, live ? h('span', null, `${call.model} · ${call.voice} · ${call.personaLabel} · `, h(Elapsed, { since: call.startedAt })) : 'Full-duplex voice with your Hermes agent'),
        call.phase === 'error' ? h('div', { className: 'glive-error' }, call.error) : null,
        status && status.ok === false ? h('div', { className: 'glive-error' }, status.error || 'The Gemini Live backend is not reachable. Is the plugin enabled?') : null,
        notConfigured
          ? h(
              'div',
              { className: 'glive-setup' },
              h('div', { className: 'glive-strong' }, 'Add your Gemini API key to start'),
              h('div', { className: 'glive-dim' }, 'Get one at aistudio.google.com/apikey, then run: hermes config set GEMINI_LIVE_API_KEY <key> (or add it under Keys).')
            )
          : null,
        h(
          'div',
          { className: 'glive-controls' },
          live
            ? [
                h(Button, { key: 'mute', onClick: () => engine.toggleMute(), variant: 'secondary' }, call.muted ? 'Unmute' : 'Mute'),
                h(Button, { key: 'end', onClick: () => void engine.stop(), variant: 'destructive' }, 'End call')
              ]
            : h(Button, { disabled: Boolean(notConfigured), onClick: () => void engine.start({ model, voice, persona }) }, 'Start call')
        ),
        h(
          'div',
          { className: 'glive-pickers' },
          h(Field, { disabled: live, label: 'Model', onChange: v => setChoice(c => Object.assign({}, c, { model: v })), options: modelOptions, value: model }),
          h(Field, {
            label: 'Voice',
            onChange: v => {
              setChoice(c => Object.assign({}, c, { voice: v }))
              if (live) engine.switchVoice(v)
            },
            options: voiceOptions,
            value: voice
          }),
          h(Field, {
            label: 'Persona',
            onChange: v => {
              setChoice(c => Object.assign({}, c, { persona: v }))
              if (live) engine.switchPersona(v)
            },
            options: personaOptions,
            value: persona
          })
        ),
        live
          ? h(
              'form',
              {
                className: 'glive-type',
                onSubmit: e => {
                  e.preventDefault()
                  if (engine.sendText(text)) setText('')
                }
              },
              h('input', { className: 'glive-input', onChange: e => setText(e.target.value), placeholder: 'Or type to the voice…', value: text })
            )
          : null,
        status && status.memory_provider ? h('div', { className: 'glive-dim glive-small' }, `Memory: ${status.memory_provider}`) : null
      ),
      h(
        'section',
        { className: 'glive-side' },
        h(
          'div',
          { className: 'glive-tabs' },
          [
            ['transcript', 'Transcript'],
            ['activity', 'Activity'],
            ['threads', 'Threads']
          ].map(([id, label]) => h('button', { className: tab === id ? 'glive-tab glive-tab--on' : 'glive-tab', key: id, onClick: () => setTab(id), type: 'button' }, label))
        ),
        tab === 'transcript' ? h(TranscriptView, { call }) : null,
        tab === 'activity' ? h(ActivityView, { call }) : null,
        h('div', { style: { display: tab === 'threads' ? 'contents' : 'none' } }, h(ThreadsView, { visible: tab === 'threads' }))
      )
    )
  }

  window.__HERMES_PLUGINS__.register('gemini-live', GeminiLivePage)
})()
